// Idiomatic Swift API layer on top of the UniFFI-generated `*Ffi` bindings
// in WalletKit.swift (autogenerated, not hand-edited).
// See `Docs/Design Specification/` for the target shape this file
// implements. The raw generated types use function-call syntax for
// everything (UniFFI doesn't generate Swift computed properties), so this
// file wraps them with the idiomatic properties/statics/defaults the
// design spec describes.

import Foundation

// MARK: - Errors

public enum WalletKitError: Error, Equatable {
    case invalidMnemonic(reason: String)
    case invalidEntropy
    case invalidPassphrase
    case invalidDerivationPath(path: String)
    case invalidAddress(reason: String)
    case unsupportedCurve(curve: Curve)
    case unsupportedWordCount(count: UInt32)
    case signingFailed(reason: String)
    case keyNotFound
    case decryptionFailed
    case internalError(message: String)

    case deviceNotFound
    case deviceDisconnected
    case deviceLocked
    case deviceBusy
    case userRejectedOnDevice
    case transportUnavailable(reason: String)
    case unsupportedDevice(reason: String)
    case firmwareOutdated(minimumVersion: String)

    init(_ raw: WalletKitErrorFfi) {
        switch raw {
        case .InvalidMnemonic(let reason): self = .invalidMnemonic(reason: reason)
        case .InvalidEntropy: self = .invalidEntropy
        case .InvalidPassphrase: self = .invalidPassphrase
        case .InvalidDerivationPath(let path): self = .invalidDerivationPath(path: path)
        case .InvalidAddress(let reason): self = .invalidAddress(reason: reason)
        case .UnsupportedCurve(let curve): self = .unsupportedCurve(curve: curve)
        case .UnsupportedWordCount(let count): self = .unsupportedWordCount(count: count)
        case .SigningFailed(let reason): self = .signingFailed(reason: reason)
        case .KeyNotFound: self = .keyNotFound
        case .DecryptionFailed: self = .decryptionFailed
        case .InternalError(let message): self = .internalError(message: message)
        case .DeviceNotFound: self = .deviceNotFound
        case .DeviceDisconnected: self = .deviceDisconnected
        case .DeviceLocked: self = .deviceLocked
        case .DeviceBusy: self = .deviceBusy
        case .UserRejectedOnDevice: self = .userRejectedOnDevice
        case .TransportUnavailable(let reason): self = .transportUnavailable(reason: reason)
        case .UnsupportedDevice(let reason): self = .unsupportedDevice(reason: reason)
        case .FirmwareOutdated(let minimumVersion): self = .firmwareOutdated(minimumVersion: minimumVersion)
        }
    }
}

/// Runs `body`, translating any thrown `WalletKitErrorFfi` (from the raw
/// generated bindings) into the public `WalletKitError`.
func remappingWalletKitError<T>(_ body: () throws -> T) rethrows -> T {
    do {
        return try body()
    } catch let error as WalletKitErrorFfi {
        throw WalletKitError(error)
    }
}

// MARK: - MnemonicWordCount

extension MnemonicWordCount: RawRepresentable {
    public typealias RawValue = UInt32

    public var rawValue: UInt32 {
        switch self {
        case .words12: return 12
        case .words15: return 15
        case .words18: return 18
        case .words21: return 21
        case .words24: return 24
        }
    }

    public init?(rawValue: UInt32) {
        switch rawValue {
        case 12: self = .words12
        case 15: self = .words15
        case 18: self = .words18
        case 21: self = .words21
        case 24: self = .words24
        default: return nil
        }
    }
}

// MARK: - CoinType / Blockchain

extension CoinType {
    public static let bitcoin = CoinType(slip44Index: 0, curve: .secp256k1, identifier: "bitcoin")
    public static let ethereum = CoinType(slip44Index: 60, curve: .secp256k1, identifier: "ethereum")
    public static let tron = CoinType(slip44Index: 195, curve: .secp256k1, identifier: "tron")
    public static let solana = CoinType(slip44Index: 501, curve: .ed25519, identifier: "solana")
    public static let cardano = CoinType(slip44Index: 1815, curve: .ed25519, identifier: "cardano")
    public static let sui = CoinType(slip44Index: 784, curve: .ed25519, identifier: "sui")
}

extension Blockchain {
    public static let bitcoin = Blockchain(coinType: .bitcoin, purpose: 44)
    public static let ethereum = Blockchain(coinType: .ethereum, purpose: 44)
    public static let tron = Blockchain(coinType: .tron, purpose: 44)
    public static let solana = Blockchain(coinType: .solana, purpose: 44)
    public static let cardano = Blockchain(coinType: .cardano, purpose: 44)
    public static let sui = Blockchain(coinType: .sui, purpose: 44)

    public var curve: Curve { coinType.curve }
    public var identifier: String { coinType.identifier }

    public func derivationPath(account: UInt32 = 0, change: UInt32 = 0, index: UInt32 = 0) -> DerivationPath {
        guard curve == .ed25519 else {
            return .bip44(purpose: purpose, coinType: coinType, account: account, change: change, index: index)
        }
        // SLIP-0010 (ed25519) only supports hardened derivation, unlike
        // BIP32's mixed hardened/non-hardened convention.
        return DerivationPath(segments: [
            Segment(index: purpose, hardened: true),
            Segment(index: coinType.slip44Index, hardened: true),
            Segment(index: account, hardened: true),
            Segment(index: change, hardened: true),
            Segment(index: index, hardened: true),
        ])
    }
}

// MARK: - DerivationPath

extension DerivationPath {
    public init(string: String) throws {
        var parts = string.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
        guard !parts.isEmpty, parts.removeFirst() == "m" else {
            throw WalletKitError.invalidDerivationPath(path: string)
        }

        var segments: [Segment] = []
        for part in parts {
            guard !part.isEmpty else {
                throw WalletKitError.invalidDerivationPath(path: string)
            }
            let hardened = part.hasSuffix("'") || part.hasSuffix("h") || part.hasSuffix("H")
            let digits = hardened ? String(part.dropLast()) : part
            guard let index = UInt32(digits) else {
                throw WalletKitError.invalidDerivationPath(path: string)
            }
            segments.append(Segment(index: index, hardened: hardened))
        }

        guard !segments.isEmpty else {
            throw WalletKitError.invalidDerivationPath(path: string)
        }
        self.init(segments: segments)
    }

    public var string: String {
        var result = "m"
        for segment in segments {
            result += "/\(segment.index)"
            if segment.hardened {
                result += "'"
            }
        }
        return result
    }

    public static func bip44(
        purpose: UInt32 = 44,
        coinType: CoinType,
        account: UInt32 = 0,
        change: UInt32 = 0,
        index: UInt32 = 0
    ) -> DerivationPath {
        DerivationPath(segments: [
            Segment(index: purpose, hardened: true),
            Segment(index: coinType.slip44Index, hardened: true),
            Segment(index: account, hardened: true),
            Segment(index: change, hardened: false),
            Segment(index: index, hardened: false),
        ])
    }
}

// MARK: - Seed

public protocol SeedProtocol: AnyObject {
    func masterKey(curve: Curve) throws -> ExtendedKey
    func exportRaw() -> Data
}

public final class Seed: SeedProtocol {
    let raw: SeedFfi

    init(raw: SeedFfi) {
        self.raw = raw
    }

    public func masterKey(curve: Curve) throws -> ExtendedKey {
        ExtendedKey(raw: raw.masterKey(curve: curve))
    }

    public func exportRaw() -> Data {
        raw.exportRaw()
    }
}

// MARK: - Mnemonic

public protocol MnemonicProtocol: AnyObject {
    var phrase: String { get }
    var wordCount: MnemonicWordCount { get }
    var wordlist: Wordlist { get }
    func toSeed(passphrase: String) -> Seed
}

public final class Mnemonic: MnemonicProtocol {
    let raw: MnemonicFfi

    init(raw: MnemonicFfi) {
        self.raw = raw
    }

    public static func generate(wordCount: MnemonicWordCount = .words24, wordlist: Wordlist = .english) -> Mnemonic {
        Mnemonic(raw: MnemonicFfi.generate(wordCount: wordCount, wordlist: wordlist))
    }

    public static func fromPhrase(_ phrase: String, wordlist: Wordlist = .english) throws -> Mnemonic {
        try remappingWalletKitError {
            Mnemonic(raw: try MnemonicFfi.fromPhrase(phrase: phrase, wordlist: wordlist))
        }
    }

    public var phrase: String { raw.phrase() }
    public var wordCount: MnemonicWordCount { raw.wordCount() }
    public var wordlist: Wordlist { raw.wordlist() }

    public func toSeed(passphrase: String = "") -> Seed {
        Seed(raw: raw.toSeed(passphrase: passphrase))
    }
}

