// MARK: - PrivateKey

public protocol PrivateKeyProtocol: AnyObject {
    var curve: Curve { get }
    var publicKey: PublicKey { get }
    func sign(message: Data) throws -> Data
}

public final class PrivateKey: PrivateKeyProtocol {
    let raw: PrivateKeyFfi

    init(raw: PrivateKeyFfi) {
        self.raw = raw
    }

    /// Imports a private key directly from raw bytes — e.g. an externally
    /// held key, or (in tests) a shared test vector — bypassing
    /// mnemonic/BIP32 derivation entirely.
    ///
    /// Throws `.signingFailed` if `rawBytes.count != 32`, or (secp256k1
    /// only) if the 32 bytes aren't a valid scalar in the curve's order.
    public init(curve: Curve, rawBytes: Data) throws {
        raw = try remappingWalletKitError { try PrivateKeyFfi.fromRawBytes(curve: curve, rawBytes: rawBytes) }
    }

    public var curve: Curve { raw.curve() }
    public var publicKey: PublicKey { PublicKey(raw: raw.publicKey()) }

    public func sign(message: Data) throws -> Data {
        try remappingWalletKitError { try raw.sign(message: message) }
    }
}

// MARK: - ExtendedKey

public protocol ExtendedKeyProtocol: AnyObject {
    var curve: Curve { get }
    var scheme: DerivationScheme { get }
    var depth: UInt8 { get }
    var childIndex: UInt32 { get }
    var isHardened: Bool { get }
    var canDerivePrivate: Bool { get }

    func derive(_ path: DerivationPath) throws -> ExtendedKey
    func deriveChild(index: UInt32, hardened: Bool) throws -> ExtendedKey

    var publicKey: PublicKey { get }
    func privateKey() throws -> PrivateKey

    func serializedPublic() -> String
    func serializedPrivate() throws -> String
}

public final class ExtendedKey: ExtendedKeyProtocol {
    let raw: ExtendedKeyFfi

    init(raw: ExtendedKeyFfi) {
        self.raw = raw
    }

    public static func fromSerialized(_ string: String, curve: Curve) throws -> ExtendedKey {
        try remappingWalletKitError {
            ExtendedKey(raw: try ExtendedKeyFfi.fromSerialized(string: string, curve: curve))
        }
    }

    public var curve: Curve { raw.curve() }
    public var scheme: DerivationScheme { raw.scheme() }
    public var depth: UInt8 { raw.depth() }
    public var childIndex: UInt32 { raw.childIndex() }
    public var isHardened: Bool { raw.isHardened() }
    public var canDerivePrivate: Bool { raw.canDerivePrivate() }

    public func derive(_ path: DerivationPath) throws -> ExtendedKey {
        try remappingWalletKitError { ExtendedKey(raw: try raw.derive(path: path)) }
    }

    public func deriveChild(index: UInt32, hardened: Bool) throws -> ExtendedKey {
        try remappingWalletKitError { ExtendedKey(raw: try raw.deriveChild(index: index, hardened: hardened)) }
    }

    public var publicKey: PublicKey { PublicKey(raw: raw.publicKey()) }

    public func privateKey() throws -> PrivateKey {
        try remappingWalletKitError { PrivateKey(raw: try raw.privateKey()) }
    }

    public func serializedPublic() -> String {
        raw.serializedPublic()
    }

    public func serializedPrivate() throws -> String {
        try remappingWalletKitError { try raw.serializedPrivate() }
    }
}

// MARK: - Accounts

public enum KeySource: Equatable {
    case software
    case hardware(HardwareDeviceInfo)
}

public protocol KeyProvider: AnyObject {
    var source: KeySource { get }
    func publicKey(path: DerivationPath, curve: Curve) async throws -> PublicKey
    func account(_ blockchain: Blockchain, account: UInt32) async throws -> Account
}

public protocol AccountProtocol: AnyObject {
    var blockchain: Blockchain { get }
    var derivationPath: DerivationPath { get }
    var curve: Curve { get }
    var source: KeySource { get }
    var publicKey: PublicKey { get }
}

public final class Account: AccountProtocol {
    public let blockchain: Blockchain
    public let derivationPath: DerivationPath
    public let curve: Curve
    public let source: KeySource
    public let publicKey: PublicKey

    init(blockchain: Blockchain, derivationPath: DerivationPath, curve: Curve, source: KeySource, publicKey: PublicKey) {
        self.blockchain = blockchain
        self.derivationPath = derivationPath
        self.curve = curve
        self.source = source
        self.publicKey = publicKey
    }
}

// MARK: - Wallet / WalletBackup

public protocol WalletProtocol: KeyProvider {
    var mnemonic: Mnemonic { get }
    func derive(_ path: DerivationPath, curve: Curve) throws -> ExtendedKey
    func exportBackup() -> WalletBackup
    func exportEncryptedBackup(password: String) throws -> Data
}

public final class Wallet: WalletProtocol {
    let raw: WalletFfi

    init(raw: WalletFfi) {
        self.raw = raw
    }

    public static func create(wordCount: MnemonicWordCount = .words24) -> Wallet {
        // `wordCount` is always a valid BIP39 count, so this can't fail.
        try! Wallet(raw: WalletFfi.create(wordCount: wordCount.rawValue, passphrase: ""))
    }

    public static func restore(phrase: String, passphrase: String = "") throws -> Wallet {
        try remappingWalletKitError {
            Wallet(raw: try WalletFfi.restore(phrase: phrase, passphrase: passphrase))
        }
    }

    public static func restoreEncrypted(data: Data, password: String) throws -> Wallet {
        try remappingWalletKitError {
            Wallet(raw: try WalletFfi.restoreEncrypted(data: data, password: password))
        }
    }

    public var mnemonic: Mnemonic { Mnemonic(raw: raw.mnemonic()) }
    public var source: KeySource { .software }

    public func publicKey(path: DerivationPath, curve: Curve) async throws -> PublicKey {
        try derive(path, curve: curve).publicKey
    }

    public func account(_ blockchain: Blockchain, account: UInt32 = 0) async throws -> Account {
        let path = blockchain.derivationPath(account: account)
        let key = try derive(path, curve: blockchain.curve)
        return Account(blockchain: blockchain, derivationPath: path, curve: blockchain.curve, source: .software, publicKey: key.publicKey)
    }

    public func derive(_ path: DerivationPath, curve: Curve) throws -> ExtendedKey {
        try remappingWalletKitError { ExtendedKey(raw: try raw.derive(path: path, curve: curve)) }
    }

    public func exportBackup() -> WalletBackup {
        raw.exportBackup()
    }

    public func exportEncryptedBackup(password: String) throws -> Data {
        try remappingWalletKitError { try raw.exportEncryptedBackup(password: password) }
    }
}

// MARK: - BlockchainAddress / BlockchainClient / HardwareSigner

public protocol BlockchainAddress: Equatable {
    var string: String { get }
    var rawBytes: Data { get }
    init(string: String) throws
    init(rawBytes: Data) throws
}

public protocol BlockchainClient {
    associatedtype Address: BlockchainAddress
    var blockchain: Blockchain { get }
    func address(for account: Account) throws -> Address
    func sign(transaction: Data, account: Account) async throws -> Data
}

public protocol HardwareSigner {
    associatedtype UnsignedTransaction
    associatedtype SignedTransaction
    func sign(_ transaction: UnsignedTransaction, account: Account, device: HardwareDevice) async throws -> SignedTransaction
}

// MARK: - Ethereum

public struct EthereumAddress: BlockchainAddress {
    let raw: EthereumAddressFfi

    init(raw: EthereumAddressFfi) {
        self.raw = raw
    }

    public var string: String { raw.string() }
    public var rawBytes: Data { raw.rawBytes() }

    /// Ethereum-specific alias for `string`, for call sites that already
    /// know they're holding an `EthereumAddress` rather than an
    /// `any BlockchainAddress`.
    public var checksummed: String { string }

    public init(string: String) throws {
        raw = try remappingWalletKitError { try EthereumAddressFfi.fromString(string: string) }
    }

    public init(rawBytes: Data) throws {
        raw = try remappingWalletKitError { try EthereumAddressFfi(rawBytes: rawBytes) }
    }

    public static func == (lhs: EthereumAddress, rhs: EthereumAddress) -> Bool {
        lhs.rawBytes == rhs.rawBytes
    }
}

/// First concrete `BlockchainClient` conformer, backed by the
/// `walletkit-ethereum`-equivalent Rust code in `blockchain_clients/`
/// (`EthereumClientFfi`, Alloy-based). `address(for:)` is fully wired up;
/// `sign(transaction:account:)` is not yet — `Account` doesn't currently
/// carry (or expose a way to recover) the private key material a software
/// signature needs, and hardware signing needs the `HardwareSigner` routing
/// described in `BlockchainClient`'s spec. Use
/// `sign(transaction:privateKey:)` directly with a key you've already
/// derived (e.g. via `Wallet.derive(_:curve:).privateKey()`) until that
/// Account → signing-key lookup exists.
public final class EthereumClient: BlockchainClient {
    public typealias Address = EthereumAddress

    public let blockchain: Blockchain = .ethereum
    let raw: EthereumClientFfi

    public init() {
        raw = EthereumClientFfi()
    }

    public func address(for account: Account) throws -> EthereumAddress {
        try address(for: account.publicKey)
    }

    public func address(for publicKey: PublicKey) throws -> EthereumAddress {
        try remappingWalletKitError { EthereumAddress(raw: try raw.address(publicKey: publicKey.raw)) }
    }

    public func sign(transaction: Data, account: Account) async throws -> Data {
        throw WalletKitError.internalError(
            message: "EthereumClient.sign(transaction:account:) needs Account to expose its signing key, "
                + "which isn't wired up yet — use sign(transaction:privateKey:) instead"
        )
    }

    /// Signs `transaction` — the RLP-encoded EIP-155 signing data described
    /// in `EthereumClient`'s design spec — with `privateKey` directly,
    /// returning the RLP-encoded signed transaction.
    public func sign(transaction: Data, privateKey: PrivateKey) async throws -> Data {
        try remappingWalletKitError { try raw.sign(signingData: transaction, privateKey: privateKey.raw) }
    }
}

// MARK: - Hardware (data/protocol shapes; no real transport lands yet)

public enum HardwareVendor: Equatable, CaseIterable {
    case trezor
}

public enum HardwareTransportKind: Equatable, CaseIterable {
    case usb
    case bluetooth
    case qrAirGap
}

public struct HardwareDeviceInfo: Equatable {
    public let id: String
    public let vendor: HardwareVendor
    public let transport: HardwareTransportKind
    public let model: String
    public let label: String?
    public let firmwareVersion: String?
    public let needsFirmwareUpdate: Bool

    public init(
        id: String,
        vendor: HardwareVendor,
        transport: HardwareTransportKind,
        model: String,
        label: String?,
        firmwareVersion: String?,
        needsFirmwareUpdate: Bool
    ) {
        self.id = id
        self.vendor = vendor
        self.transport = transport
        self.model = model
        self.label = label
        self.firmwareVersion = firmwareVersion
        self.needsFirmwareUpdate = needsFirmwareUpdate
    }
}

public enum HardwareInputRequest: Equatable {
    case pin(attempt: UInt32)
    case passphrase
}

public enum HardwareButtonRequest: Equatable {
    case confirmAddress
    case confirmPublicKey
    case confirmTransaction
    case other(description: String)
}

public protocol HardwareDeviceDelegate: AnyObject {
    func hardwareDevice(_ device: HardwareDevice, needsInput request: HardwareInputRequest) async -> String?
    func hardwareDevice(_ device: HardwareDevice, waitingForConfirmation request: HardwareButtonRequest) async
    func hardwareDeviceDidDisconnect(_ device: HardwareDevice)
}

public protocol HardwareDeviceProtocol: KeyProvider {
    var info: HardwareDeviceInfo { get }
    var isConnected: Bool { get }
    func disconnect() async
}

public final class HardwareDevice: HardwareDeviceProtocol {
    public let info: HardwareDeviceInfo
    public private(set) var isConnected: Bool
    private weak var delegate: HardwareDeviceDelegate?

    init(info: HardwareDeviceInfo, delegate: HardwareDeviceDelegate?) {
        self.info = info
        self.delegate = delegate
        self.isConnected = true
    }

    public var source: KeySource { .hardware(info) }

    public func publicKey(path: DerivationPath, curve: Curve) async throws -> PublicKey {
        throw WalletKitError.deviceDisconnected
    }

    public func account(_ blockchain: Blockchain, account: UInt32 = 0) async throws -> Account {
        throw WalletKitError.deviceDisconnected
    }

    public func disconnect() async {
        isConnected = false
        delegate?.hardwareDeviceDidDisconnect(self)
    }
}

public protocol HardwareDeviceManagerProtocol: AnyObject {
    func scan(vendors: [HardwareVendor], transports: [HardwareTransportKind]) async throws -> [HardwareDeviceInfo]
    func connect(_ info: HardwareDeviceInfo, delegate: HardwareDeviceDelegate) async throws -> HardwareDevice
}

public final class HardwareDeviceManager: HardwareDeviceManagerProtocol {
    public init() {}

    public func scan(
        vendors: [HardwareVendor] = HardwareVendor.allCases,
        transports: [HardwareTransportKind] = [.usb, .bluetooth]
    ) async throws -> [HardwareDeviceInfo] {
        guard !transports.isEmpty else {
            throw WalletKitError.transportUnavailable(reason: "no transports requested")
        }
        // No real transport (USB/Bluetooth) integration yet, so nothing is
        // ever discovered — correct behavior with no device connected.
        return []
    }

    public func connect(_ info: HardwareDeviceInfo, delegate: HardwareDeviceDelegate) async throws -> HardwareDevice {
        throw WalletKitError.deviceNotFound
    }
}
